contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmt)); require(depAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmt);
        c.deposit{value: depAmt}(); if (__ESBMC_reverted()) return;
        uint balAfterDep = address(c).balance;
        uint balBeforeWd = balAfterDep;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint balAfterWd = address(c).balance;

        assert(balAfterWd == balBeforeWd - depAmt);
    }

    receive() external payable {}
}

